package com.cenedu.backend.ai.problem.render;
import com.cenedu.backend.domain.problem.authoring.diagram.*; import com.cenedu.backend.domain.problem.authoring.semantic.evaluation.SemanticResolvedValue; import java.util.*;
public final class SolidGeometrySvgRenderer { public String render(SolidGeometryDiagramSpecV1 s){return render(s,Map.of());} public String render(SolidGeometryDiagramSpecV1 s,Map<String,SemanticResolvedValue> values){int p=s.viewport().padding(),w=s.viewport().width(),h=s.viewport().height();int width=scaled(values,s.widthKey(),w-2*p),depth=scaled(values,s.depthKey(),40),height=scaled(values,s.heightKey(),h-2*p);int x=p,y=h-p-height;var b=new StringBuilder("<polygon points=\"").append(x).append(",").append(h-p).append(" ").append(x+width).append(",").append(h-p).append(" ").append(x+width-depth).append(",").append(y+23).append(" ").append(x+depth).append(",").append(y).append("\" fill=\"none\" stroke=\"#000000\"/>");b.append("<line x1=\"").append(x).append("\" y1=\"").append(h-p).append("\" x2=\"").append(x+depth).append("\" y2=\"").append(y).append("\" stroke=\"#000000\" stroke-dasharray=\"4 3\"/>");for(var label:s.labels()){String text=label.labelTemplate();var value=values.get(label.valueKey());if(value!=null)text+=" "+value.canonicalValue();b.append("<text x=\"").append(x+8).append("\" y=\"").append(Math.max(14,y+18)).append("\">").append(escape(text)).append("</text>");}return b.toString();}private int scaled(Map<String,SemanticResolvedValue> v,String key,int fallback){try{return Math.max(8,Math.min(fallback,Integer.parseInt(v.get(key).canonicalValue())*10));}catch(Exception e){return Math.max(8,fallback/2);}}private String escape(String s){return s==null?"":s.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;");} }
